    price_order([{'sku': 'PEN', 'quantity': 1}, {'sku': 'MUG', 'quantity': 1}], catalog)
except ValueError as exc:
    assert 'mixed' in str(exc)
else:
    raise AssertionError('expected mixed-currency order to fail')
PY
